REGISTRY = {}


def command(name, help_text):
    def register(fn):
        REGISTRY[name] = (fn, help_text)
        return fn
    return register


def run(line):
    name, *args = line.split()
    if name not in REGISTRY:
        return "unknown command: " + name
    return REGISTRY[name][0](args)


@command("ping", "Reply with pong")
def ping(args):
    return "pong"


@command("echo", "Print the arguments")
def echo(args):
    return " ".join(args)


@command("help", "List the commands")
def help_(args):
    return "\n".join("%s - %s" % (n, REGISTRY[n][1]) for n in sorted(REGISTRY))

