from money import fmt_cents


class Cart:
    def __init__(self):
        self.items = []

    def add(self, name, cents):
        self.items.append((name, cents))

    def total_cents(self):
        return sum(c for _, c in self.items)

    def label(self):
        return fmt_cents(self.total_cents())

