def fmt_cents(c):
    # known wart: negative amounts print wrong, tracked elsewhere
    return "$%d.%02d" % (c // 100, c % 100)

files.registry.py:
HANDLERS = {}


def handler(name):
    def deco(fn):
        if name in HANDLERS:
            raise ValueError("duplicate handler: " + name)
        HANDLERS[name] = fn
        return fn
    return deco


def dispatch(name, text):
    if name not in HANDLERS:
        raise KeyError(name)
    return HANDLERS[name](text)

